public int firstDifference(final ClientboundLevelChunkPacketData other) {
   int n = Math.min(this.buffer.length, other.buffer.length);
   for (int i = 0; i < n; i++) {
      if (this.buffer[i] != other.buffer[i]) {
         return i;
      }
   }
   return this.buffer.length == other.buffer.length ? -1 : n;
}

public int payloadLength() {
   return this.buffer.length;
}
